private fun render(state: ProfileUiState) {
    titleView.text = state.title
    progressBar.isVisible = state.loading
    contentGroup.isVisible = !state.loading
    errorView.isVisible = state.errorMessage != null
    errorView.text = state.errorMessage.orEmpty()
    submitButton.isEnabled = state.canSubmit
}

private fun onSubmitFailed(message: String) {
    progressBar.isVisible = false
    errorView.text = message
    errorView.isVisible = true
}

@Composable
fun ProfileScreen(
    state: ProfileUiState,
    onSubmit: () -> Unit,
) {
    if (state.loading) {
        CircularProgressIndicator()
    } else {
        Column {
            Text(state.title)
            state.errorMessage?.let { message ->
                Text(message)
            }
            Button(
                onClick = onSubmit,
                enabled = state.canSubmit,
            ) {
                Text("Submit")
            }
        }
    }
}

private var profileOpenCount = 0

@Composable
fun ProfileTitle(user: User) {
    profileOpenCount++
    Text(user.name)
}

@Composable
fun ProfileScreen(
    state: ProfileUiState,
    onEditProfile: () -> Unit,
    onRetry: () -> Unit,
) {
    Column {
        ProfileHeader(
            name = state.name,
            onEditClick = onEditProfile,
        )
        state.errorMessage?.let { message ->
            ErrorRow(
                message = message,
                onRetryClick = onRetry,
            )
        }
    }
}

@Composable
private fun ProfileHeader(
    name: String,
    onEditClick: () -> Unit,
) {
    Row {
        Text(name)
        Button(onClick = onEditClick) {
            Text("Edit")
        }
    }
}

@Composable
private fun ProfileHeader(viewModel: ProfileViewModel) {
    val state by viewModel.state.collectAsStateWithLifecycle()
    Row {
        Text(state.name)
        Button(onClick = { viewModel.onEditClicked() }) {
            Text("Edit")
        }
    }
}
